   $$natuurkunde-vwo-2017-i-inwendige-bestraling-vraag21.png$$, $$Geef de beide reactievergelijkingen die leiden tot de vorming van I-125.$$, array['5e4683da-254b-4250-a536-ceeecc8cba49']::uuid[]),
