   $$natuurkunde-vwo-2017-i-inwendige-bestraling-vraag22.png$$, $$Bereken de massa I-125 in kg die daartoe tijdens de productie in één naaldje moet worden aangebracht.$$, array['5fb058ae-948d-48e0-ba73-347cc97e02d9']::uuid[]),
