   $$natuurkunde-vwo-2017-i-inwendige-bestraling-vraag23.png$$, $$Leg op grond van figuur 1 uit wie er gelijk heeft.$$, array['3e5ed552-db61-4bde-b2a0-98e52e656195']::uuid[]),
